same-term.query:
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT ?obs ?soc FROM STREAM Telemetry [NOW]
WHERE { STREAM Telemetry { ?obs sosa:hasSimpleResult ?soc } FILTER(sameTerm(?soc, ?soc)) }

not-exists.query:
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT ?obs ?soc FROM STREAM Telemetry [NOW]
WHERE { STREAM Telemetry { ?obs sosa:hasSimpleResult ?soc } FILTER(?soc < 20)  FILTER NOT EXISTS { ?obs <https://example.org/fleet/missing> ?x } }

duration-ms.query:
PREFIX sosa: <http://www.w3.org/ns/sosa/>
